const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID();let db,state={trips:[],places:[],trash:[]},selected='all',view='map',pinning=false,map,layer;const modal=$('modal');function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}function show(html){modal.innerHTML='<button type="button" class="modal-x" aria-label="关闭窗口" onclick="closeModal()">×</button>'+html;if(!modal.open)modal.showModal()}function closeModal(){modal.close()}function error(e){console.error(e);toast('未能完成：'+e.message)}function persist(){return new Promise((resolve,reject)=>{const tx=db.transaction('atlas','readwrite');tx.objectStore('atlas').put(state,'data');tx.oncomplete=()=>{render();resolve()};tx.onerror=()=>reject(tx.error)})}async function commit(next){const old=state;state=next;try{await persist();if(typeof setDirty==='function')setDirty()}catch(e){state=old;render();throw e}}const visible=()=>state.places.filter(p=>selected==='all'||p.trip===selected);function render(){ if(selected&&selected!=='all'&&!state.trips.some(t=>t.id===selected))selected='all';$('trashButton').textContent='回收站'+(state.trash?.length?' · '+state.trash.length:''); $('nTrips').textContent=state.trips.length;$('nPlaces').textContent=state.places.length;$('nPhotos').textContent=state.places.reduce((n,p)=>n+p.media.length,0);$('trips').innerHTML=`<div class="trip ${selected==='all'?'selected':''}" data-trip="all"><h3>所有足迹</h3><p>世界很大，故事慢慢写。</p></div><div class="trip ${selected===''?'selected':''}" data-trip=""><h3>未分类足迹</h3><p>${state.places.filter(p=>!p.trip).length} 个地点 · 照片收件箱</p></div>`+state.trips.map(t=>`<div class="trip ${selected===t.id?'selected':''}" data-trip="${t.id}"><h3>${esc(t.name)}</h3><p>${state.places.filter(p=>p.trip===t.id).length} 个地点 · 私人手札</p></div>`).join('');document.querySelectorAll('[data-trip]').forEach(e=>e.onclick=()=>{selected=e.dataset.trip;render();fit();if(selected!=='all')tripManager(selected)});renderMap();$('gallery').hidden=view==='map';$('gallery').style.display=view==='map'?'none':'grid';$('map').style.display=view==='map'?'block':'none';$('mapTitle').hidden=view!=='map';$('mapNote').hidden=view!=='map';if(view!=='map')renderGallery();document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===view))}function fit(){if(!map)return;const ps=visible().filter(hasCoordinates);if(ps.length)map.fitBounds(ps.map(p=>[p.lat,p.lng]),{padding:[60,60],maxZoom:9})}document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{view=e.dataset.view;render();if(map)map.invalidateSize()});$('newTrip').onclick=()=>{show(`<h2>新的一段旅程</h2><form id="tripForm"><label for="tripName">旅行名称 <span class="required">*</span></label><input id="tripName" required maxlength="80" placeholder="例如：秋日京都散步"><div class="actions"><button type="button" onclick="closeModal()">取消</button><button class="primary">创建手札</button></div></form>`);$('tripForm').onsubmit=async e=>{e.preventDefault();const name=$('tripName').value.trim();if(!name)return;try{const id=uid();await commit({...state,trips:[...state.trips,{id,name}]});selected=id;render();closeModal()}catch(e){error(e)}}};let lastSearch=0;async function lookup(q){const delay=Math.max(0,1200-(Date.now()-lastSearch));if(delay)await new Promise(r=>setTimeout(r,delay));lastSearch=Date.now();const r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=4&accept-language=zh&q='+encodeURIComponent(q));if(!r.ok)throw Error('地点搜索暂不可用，请直接在地图落钉');return r.json()}
function tripOptions(id){return `<option value="">未分类足迹</option>`+state.trips.map(t=>`<option value="${t.id}" ${id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}function placeForm(coords,p){show(`<h2>${p?'编辑回忆':'收藏一个地方'}</h2><form id="placeForm"><p class="hint"><span class="required">*</span> 为必填，其余内容可稍后补充。</p><label for="placeName">地点名称 <span class="required">*</span></label><div class="row"><input id="placeName" required maxlength="160" value="${esc(p?.name||'')}" placeholder="国家 + 城市 / 地名，如 USA Savannah"><button type="button" id="search">搜索定位</button></div><p class="hint">建议输入“国家 + 城市 / 地名”，例如 USA Savannah 或 日本 京都 清水寺。中文名搜不到时，可试当地名称、英文名或国家 + 邮编（如 USA 31401），再核对结果。</p><div id="results"></div><p class="hint" id="locationHint">${coords?'已在地图选好位置':'先搜索并选择结果，也可填写经纬度。'}</p><div class="row"><div><label for="lat">纬度（选填）</label><input id="lat" type="number" step="any" min="-85" max="85" value="${p?.lat??coords?.lat??''}"></div><div><label for="lng">经度（选填）</label><input id="lng" type="number" step="any" min="-180" max="180" value="${p?.lng??coords?.lng??''}"></div></div><div class="row"><div><label for="tripSelect">所属旅行 / 分类（选填）</label><select id="tripSelect">${tripOptions(p?p.trip:(selected==='all'?'':selected))}</select>${categoryEditor("tripSelect")}</div><div><label for="date">到访日期（选填）</label><input type="date" id="date" value="${esc(p?.date||'')}"></div></div>${geoPickerMarkup(p)}<div class="row"><div><label for="visitPlaceName">统计地点名称（选填）</label><input id="visitPlaceName" maxlength="160" value="${esc(p?.visitPlace||'')}" placeholder="同一地点请使用同一名称"></div></div><p class="hint">用于到访次数统计。未填写统计名称时，按附近坐标分组；可在“到访统计”中修改次数。</p><label for="note">写下这一刻（选填）</label><textarea id="note" maxlength="10000" placeholder="那天的天气、街角的咖啡，或者同行的人……">${esc(p?.note||'')}</textarea><p class="hint">可以留空直接保存，等想写的时候再回来。</p><label for="mediaFiles">添加照片 / 邮戳扫描件（选填，可多选）</label><input type="file" id="mediaFiles" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif"><select id="kind" style="margin-top:8px"><option value="photo">旅行照片</option><option value="stamp">邮戳、盖章与票根</option></select><p class="hint">支持 JPG、PNG、WebP、HEIC / HEIF；图片会转换、压缩为静态照片保存，可在地点详情中继续添加。</p><div class="actions"><button type="button" onclick="closeModal()">取消</button><button type="submit" class="primary" id="savePlace">保存回忆</button></div></form>`);bindCategoryEditor("tripSelect");const readGeo=bindGeoPicker(p);$('search').onclick=async()=>{const q=$('placeName').value.trim();if(!q)return;$('search').disabled=true;try{const results=await lookup(q);$('results').innerHTML=results.length?results.map((r,i)=>`<button type="button" class="result" data-result="${i}">${esc(r.display_name)}</button>`).join(''):'<p class="hint">没有找到。请尝试国家 + 当地名称 / 英文名，或国家 + 邮编；也可以直接在地图落钉。</p>';document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=results[+b.dataset.result];$('lat').value=r.lat;$('lng').value=r.lon;$('locationHint').textContent=r.display_name;$('results').innerHTML=''})}catch(e){error(e)}finally{if($('search'))$('search').disabled=false}};$('placeForm').onsubmit=async e=>{e.preventDefault();$('savePlace').disabled=true;try{const media=await readMedia($('mediaFiles').files,$('kind').value);const record={id:p?.id||uid(),name:$('placeName').value.trim(),lat:$('lat').value===''?null:+$('lat').value,lng:$('lng').value===''?null:+$('lng').value,trip:$('tripSelect').value,date:$('date').value,note:$('note').value,...readGeo(),visitPlace:$('visitPlaceName').value.trim(),media:[...(p?.media||[]),...media]};if(!record.name)throw Error('请填写地点名称');if((record.lat===null)!==(record.lng===null))throw Error('请同时填写经纬度，或都留空稍后补充');await commit({...state,places:p?state.places.map(x=>x.id===p.id?record:x):[...state.places,record]});closeModal();fit();toast('回忆已保存到此浏览器')}catch(e){error(e);$('savePlace').disabled=false;}}}
async function readMedia(files,kind){const result=[];for(const f of files){if(!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(f.type)&&!(/\.(jpe?g|png|webp|hei[cf])$/i.test(f.name)))throw Error('请上传 JPG、PNG、WebP、HEIC 或 HEIF 静态照片；暂不支持实况 MOV 视频');if(f.size>25*1024*1024)throw Error('单张图片请小于 25 MB');const img=await imageBitmapForUpload(f);const scale=Math.min(1,1600/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fffaf0';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);img.close();result.push({id:uid(),name:f.name,kind,data:c.toDataURL('image/jpeg',.84)})}return result}
function detail(id){const p=state.places.find(p=>p.id===id);show(`<div class="eyebrow">A MEMORY TO KEEP</div><h2 style="margin-top:15px">${esc(p.name)}</h2>${typeof visitBadge==='function'?visitBadge(p):''}<p class="hint">${esc(p.date||'未注明日期')} · ${esc(state.trips.find(t=>t.id===p.trip)?.name||'未分类足迹')}</p><p style="white-space:pre-wrap">${esc(p.note||'给这段回忆留几句话吧。')}</p><div class="photos">${p.media.map(m=>`<div><button class="photo-open" data-open-photo="${m.id}" aria-label="放大 ${esc(m.name)}"><img src="${m.data}" alt="${esc(m.name)}"></button><p class="hint">${m.kind==='stamp'?'◉ 邮戳 / 印章':'▧ 照片'} <button data-remove="${m.id}" style="padding:4px">移除</button></p></div>`).join('')}</div><div class="actions"><button id="deletePlace">删除地点</button><button onclick="closeModal()">关闭</button><button class="primary" id="editPlace">编辑 / 添加藏品</button></div>`);modal.querySelectorAll('[data-open-photo]').forEach(b=>b.onclick=()=>openViewer(p.id,b.dataset.openPhoto));$('editPlace').onclick=()=>{closeModal();placeForm(null,p)};$('deletePlace').onclick=async()=>{if(!confirm('将这个地点及其藏品移入回收站？之后可恢复。'))return;try{await commit(TrashModel.removePlaces(state,[id]));closeModal();toast('地点已移入回收站')}catch(e){error(e)}};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('将这份藏品移入回收站？之后可恢复。'))return;try{await commit(TrashModel.removeMedia(state,id,b.dataset.remove));detail(id);toast('藏品已移入回收站')}catch(e){error(e)}})}$('add').onclick=()=>placeForm();$('pin').onclick=()=>{if(!map){toast('地图尚未加载，请检查网络后刷新');return}view='map';pinning=!pinning;render();map.invalidateSize();$('pin').classList.toggle('primary',pinning);$('mapNote').textContent=pinning?'点击地图任意位置，收藏新的足迹':'拖动探索世界 · 点击图钉翻阅回忆';map.getContainer().style.cursor=pinning?'crosshair':''};
$('batch').onclick=()=>batchForm();
$('route').onclick=()=>{if(selected!=='all'){tripManager(selected);return}show(`<h2>整理旅行手札</h2><p class="hint">选择旅程，编辑地点与路线顺序。</p>${state.trips.map(t=>`<button class="result" data-organize="${t.id}">${esc(t.name)} →</button>`).join('')||'<p class="hint">先创建一本旅行手札。</p>'}`);modal.querySelectorAll('[data-organize]').forEach(b=>b.onclick=()=>{selected=b.dataset.organize;render();fit();tripManager(selected)})};
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}$('export').onclick=()=>download({format:'paper-atlas-v1',...state},'行迹备份-'+new Date().toISOString().slice(0,10)+'.json');$('import').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>150*1024*1024)throw Error('备份文件过大');const d=readBackup(JSON.parse(await file.text()));if(!confirm(`将添加 ${d.trips.length} 本手札、${d.places.length} 个地点和 ${d.trash.length} 项回收站记录，保留现有内容。继续？`))return;await commit({...state,geoTags:[...new Map([...(state.geoTags||[]),...(d.geoTags||[])].map(t=>[t.id,t])).values()],trips:[...state.trips,...d.trips],places:[...state.places,...d.places],trash:[...(state.trash||[]),...d.trash],visitCounts:{...(state.visitCounts||{}),...d.visitCounts}});fit();toast('备份已导入')}catch(e){error(e)}finally{e.target.value=''}};

async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('paper-atlas',1);r.onupgradeneeded=()=>r.result.createObjectStore('atlas');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const saved=await new Promise((resolve,reject)=>{const r=db.transaction('atlas').objectStore('atlas').get('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved)state={...saved,trash:saved.trash||[]};if(window.L){map=L.map('map',{minZoom:2,maxZoom:18,worldCopyJump:true}).setView([27,55],2);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);layer=L.layerGroup().addTo(map);map.on('zoomend',renderMap);map.on('click',e=>{if(!pinning)return;pinning=false;$('pin').classList.remove('primary');map.getContainer().style.cursor='';$('mapNote').textContent='拖动探索世界 · 点击图钉翻阅回忆';placeForm({lat:+e.latlng.lat.toFixed(6),lng:+e.latlng.wrap().lng.toFixed(6)})})}else $('map').innerHTML='<div class="empty">地图暂未加载，请连接网络后刷新。已有收藏仍可浏览。</div>';render();fit()}catch(e){error(e)}}init();

function categoryEditor(target){return `<button type="button" id="${target}New" class="new-category" aria-expanded="false">＋ 新建分类</button><div id="${target}Editor" class="category-editor" hidden><label for="${target}Name">新分类名称 <span class="required">*</span></label><input id="${target}Name" maxlength="80" placeholder="例如：日本旅行、周末散步"><p class="hint" id="${target}Error" role="status"></p><div class="row"><button type="button" id="${target}Cancel">取消新建</button><button type="button" id="${target}Create">创建并选中</button></div></div>`}
function bindCategoryEditor(target){const toggle=$(target+'New'),panel=$(target+'Editor'),input=$(target+'Name'),create=$(target+'Create'),cancel=$(target+'Cancel'),message=$(target+'Error');toggle.onclick=()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)input.focus()};cancel.onclick=()=>{panel.hidden=true;toggle.setAttribute('aria-expanded','false');message.textContent=''};create.onclick=async()=>{const name=input.value.trim();if(!name){message.textContent='请填写新分类名称。';input.focus();return}create.disabled=true;cancel.disabled=true;try{let trip=state.trips.find(t=>t.name===name);if(!trip){trip={id:uid(),name};await commit({...state,trips:[...state.trips,trip]})}$(target).innerHTML=tripOptions(trip.id);panel.hidden=true;toggle.setAttribute('aria-expanded','false');input.value='';message.textContent='';toast('已选中分类：'+name)}catch(e){message.textContent='创建失败，请重试。';error(e)}finally{create.disabled=false;cancel.disabled=false}};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();create.click()}}}
function cleanMarker(m){return {label:typeof m?.label==='string'?m.label.slice(0,64):'',frame:['circle','rounded','none'].includes(m?.frame)?m.frame:'circle',shape:['circle','square','diamond','star','image','emoji','text'].includes(m?.shape)?m.shape:'circle',color:/^#[0-9a-f]{6}$/i.test(m?.color)?m.color:'#a45f43',image:typeof m?.image==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(m.image)?m.image:''}}
function markerHTML(m){m=cleanMarker(m);if(['emoji','text'].includes(m.shape))return `<span class="letter-marker frame-${m.frame} ${m.shape}" style="--pin-color:${m.color}">${esc(m.label|| (m.shape==='emoji'?'📍':'旅'))}</span>`;return m.shape==='image'&&m.image?`<img class="custom-marker" src="${m.image}" alt="旅行图钉">`:`<span class="marker-shape ${m.shape==='image'?'circle':m.shape}" style="background:${m.color}"></span>`}
function markerIcon(t,p){return L.divIcon({className:'atlas-marker',html:markerHTML(t?.marker)+(p&&typeof visitPinBadge==='function'?visitPinBadge(p):''),iconSize:[30,30],iconAnchor:[15,15]})}
function tripManager(id){const t=state.trips.find(t=>t.id===id)||(id===''?{id:'',name:'未分类足迹'}:null);if(!t)return;selected=id;const ps=state.places.filter(p=>p.trip===id);show(`<div class="eyebrow">TRAVEL JOURNAL / 管理旅行</div><h2>${esc(t.name)}</h2><div class="toolbar"><button id="tripSettings">编辑名称与图钉</button><button id="shareJourney">↗ 分享手札</button><button id="tripAdd">＋ 添加地点</button><button id="tripBatch">批量添加地点</button><button id="tripPhotos" ${ps.length?'':'disabled'}>批量上传与分配照片</button></div><p class="hint">点击地点编辑回忆；用 ↑ ↓ 调换路线顺序，修改后自动保存。勾选可批量删除。</p><label><input type="checkbox" id="selectAll" class="inline-check"> 全选地点</label><div class="place-list">${ps.map((p,i)=>`<div class="manage-place"><input type="checkbox" class="inline-check" data-check="${p.id}" aria-label="选择 ${esc(p.name)}"><button class="place-link" data-edit="${p.id}">${esc(p.name)}<small>${esc(p.date||'未注明日期')} · ${p.media.length} 份藏品</small>${typeof visitBadge==='function'?visitBadge(p):''}</button><span class="order-controls"><button data-order="${p.id}" data-direction="-1" aria-label="上移 ${esc(p.name)}" ${i===0?'disabled':''}>↑</button><button data-order="${p.id}" data-direction="1" aria-label="下移 ${esc(p.name)}" ${i===ps.length-1?'disabled':''}>↓</button></span><button data-delete="${p.id}" aria-label="删除 ${esc(p.name)}">删除</button></div>`).join('')||'<p class="hint">手札还是空的，从添加第一个地点开始。</p>'}</div><div class="actions"><button id="deleteTrip" class="danger">删除旅程</button><button id="geoSelected" disabled>设置国家 / 城市标签</button><button id="moveSelected" disabled>归入其他旅行</button><button id="deleteSelected" disabled>删除选中地点</button><button onclick="closeModal()">返回地图</button></div><div id="deleteNotice"></div>`);if(!id){['tripSettings','shareJourney','deleteTrip'].forEach(key=>$(key).hidden=true)}modal.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>movePlace(id,b.dataset.order,+b.dataset.direction));$('shareJourney').onclick=()=>shareTrip(id);$('deleteTrip').onclick=()=>confirmTripDelete(id);$('tripSettings').onclick=()=>tripSettings(id);$('tripAdd').onclick=()=>placeForm();$('tripBatch').onclick=()=>batchForm();$('tripPhotos').onclick=()=>photoForm(id);const checks=()=>[...modal.querySelectorAll('[data-check]')];function update(){$('deleteSelected').disabled=!checks().some(c=>c.checked);$('geoSelected').disabled=!checks().some(c=>c.checked);$('moveSelected').disabled=!checks().some(c=>c.checked);$('selectAll').checked=ps.length>0&&checks().every(c=>c.checked)}$('selectAll').onchange=e=>{checks().forEach(c=>c.checked=e.target.checked);update()};checks().forEach(c=>c.onchange=update);modal.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>placeForm(null,state.places.find(p=>p.id===b.dataset.edit)));modal.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>askDelete([b.dataset.delete],id));$('geoSelected').onclick=()=>batchGeoTags(checks().filter(c=>c.checked).map(c=>c.dataset.check),id);$('moveSelected').onclick=()=>moveRecords(checks().filter(c=>c.checked).map(c=>c.dataset.check),id);$('deleteSelected').onclick=()=>askDelete(checks().filter(c=>c.checked).map(c=>c.dataset.check),id)}
function askDelete(ids,trip){$('deleteNotice').innerHTML=`<div class="category-editor"><p>将 ${ids.length} 个地点及其照片、邮戳移入回收站？之后可以恢复。</p><button id="confirmDelete">移入回收站</button> <button id="cancelDelete">取消</button></div>`;$('cancelDelete').onclick=()=>$('deleteNotice').innerHTML='';$('confirmDelete').onclick=async()=>{try{await commit(TrashModel.removePlaces(state,ids));tripManager(trip);toast('地点已移入回收站')}catch(e){error(e)}}}
function tripSettings(id){const t=state.trips.find(t=>t.id===id);let m=cleanMarker(t.marker);show(`<h2>编辑旅行手札</h2><form id="settingsForm"><label for="editTripName">旅行名称 <span class="required">*</span></label><input id="editTripName" required maxlength="80" value="${esc(t.name)}"><div class="row"><div><label for="markerShape">图钉形状</label><select id="markerShape">${[['circle','圆形'],['square','方形'],['diamond','菱形'],['star','星形'],['image','自定义图片'],['emoji','Emoji 表情'],['text','文字']].map(([v,n])=>`<option value="${v}" ${m.shape===v?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="markerColor">图钉颜色</label><input type="color" id="markerColor" value="${m.color}"></div></div><div id="markerLetterFields" ${['emoji','text'].includes(m.shape)?'':'hidden'}><label for="markerLabel">Emoji / 短文字 <span class="required">*</span></label><input id="markerLabel" maxlength="64" value="${esc(m.label)}" placeholder="例如：🎓、🌸、毕业、日本"><p class="hint">可输入 1–4 个文字或表情，组合表情也支持。</p><label for="markerFrame">边框样式</label><select id="markerFrame"><option value="circle" ${m.frame==='circle'?'selected':''}>圆形</option><option value="rounded" ${m.frame==='rounded'?'selected':''}>圆角方形</option><option value="none" ${m.frame==='none'?'selected':''}>无边框</option></select></div><label for="markerFile">上传图钉图片（选填）</label><input id="markerFile" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif"><p class="hint">适用于这段旅行的所有地点；上传图片后自动切换为图片图钉。</p><div id="markerPreview" class="marker-preview">${markerHTML(m)}</div><div class="actions"><button type="button" id="backManager">取消</button><button class="primary" id="saveSettings">保存设置</button></div></form>`);const refresh=()=>{m.shape=$('markerShape').value;m.color=$('markerColor').value;m.label=$('markerLabel').value.trim();m.frame=$('markerFrame').value;const letters=['emoji','text'].includes(m.shape);$('markerLetterFields').hidden=!letters;$('markerLabel').required=letters;$('markerPreview').innerHTML=markerHTML(m)};$('markerLabel').oninput=refresh;$('markerFrame').onchange=refresh;$('markerShape').onchange=refresh;refresh();$('markerColor').oninput=refresh;$('markerFile').onchange=async e=>{const input=e.target;const save=$('saveSettings');save.disabled=true;try{const media=await readMedia(input.files,'photo');if(media.length){m.image=media[0].data;$('markerShape').value='image';refresh()}}catch(e){error(e)}finally{save.disabled=false}};$('backManager').onclick=()=>tripManager(id);$('settingsForm').onsubmit=async e=>{e.preventDefault();const name=$('editTripName').value.trim();if(!name)return;if(['emoji','text'].includes(m.shape)&&(!m.label||[...new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(m.label)].length>4)){toast('请输入 1–4 个文字或表情');return}if(m.shape==='image'&&!m.image){toast('请上传图片，或选择其他图钉形状');return}try{await commit({...state,trips:state.trips.map(x=>x.id===id?{...x,name,marker:m}:x)});tripManager(id);toast('旅行名称与图钉已更新')}catch(e){error(e)}}}
function allocatorMarkup(){return `<section class="photo-allocator"><h3>照片分配台</h3><p class="hint">一次选择多张照片，再用下拉框指定地点；也可拖动照片到地点分区。每张照片都需要分配，或从本次上传中移除。</p><label for="allocationFiles">上传照片 / 邮戳（可多选）</label><input id="allocationFiles" type="file" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.heic,.heif"><div id="allocationStatus" class="hint" role="status"></div><div id="allocationZones" class="allocation-zones"></div><div id="allocationCards" class="allocation-cards"></div></section>`}
function photoAllocator(getTargets){let items=[],busy=false;const file=$('allocationFiles');function draw(){const targets=getTargets();$('allocationZones').innerHTML=targets.map(t=>`<div class="drop-zone" data-zone="${t.id}">${esc(t.name)}<small>${items.filter(m=>m.target===t.id).length} 张</small></div>`).join('');$('allocationCards').innerHTML=items.map(m=>`<div class="allocation-card" draggable="true" data-photo="${m.id}"><img src="${m.data}" alt="${esc(m.name)}"><small>${esc(m.name)}</small><label>放到哪个地点</label><select data-target="${m.id}"><option value="">请选择地点</option>${targets.map(t=>`<option value="${t.id}" ${m.target===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><label>藏品类型</label><select data-kind="${m.id}"><option value="photo" ${m.kind==='photo'?'selected':''}>照片</option><option value="stamp" ${m.kind==='stamp'?'selected':''}>邮戳 / 印章 / 票根</option></select><button data-discard="${m.id}">移除本次上传</button></div>`).join('');$('allocationStatus').textContent=busy?'正在处理图片，请稍候…':`共 ${items.length} 张，${items.filter(m=>!targets.some(t=>t.id===m.target)).length} 张待分配`;modal.querySelectorAll('[data-target]').forEach(s=>s.onchange=()=>{items.find(m=>m.id===s.dataset.target).target=s.value;draw()});modal.querySelectorAll('[data-kind]').forEach(s=>s.onchange=()=>items.find(m=>m.id===s.dataset.kind).kind=s.value);modal.querySelectorAll('[data-discard]').forEach(b=>b.onclick=()=>{items=items.filter(m=>m.id!==b.dataset.discard);draw()});modal.querySelectorAll('[data-photo]').forEach(c=>c.ondragstart=e=>e.dataTransfer.setData('text/plain',c.dataset.photo));modal.querySelectorAll('[data-zone]').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();const m=items.find(m=>m.id===e.dataTransfer.getData('text/plain'));if(m){m.target=z.dataset.zone;draw()}}})}file.onchange=async()=>{busy=true;file.disabled=true;draw();try{const additions=await readMedia(file.files,'photo');items.push(...additions.map(m=>({...m,target:''})))}catch(e){error(e)}finally{busy=false;file.disabled=false;file.value='';draw()}};draw();return{refresh:draw,collect(){if(busy)throw Error('图片仍在处理中，请稍候');const ts=getTargets();if(items.some(m=>!ts.some(t=>t.id===m.target)))throw Error('请为每张照片选择地点，或移除未分配的照片');return items.map(m=>({...m}))}}}
function photoForm(id){const targets=()=>state.places.filter(p=>p.trip===id);show(`<h2>为旅程收藏照片</h2>${allocatorMarkup()}<div class="actions"><button id="photoBack">取消</button><button class="primary" id="savePhotos">保存照片</button></div>`);const allocator=photoAllocator(targets);$('photoBack').onclick=()=>tripManager(id);$('savePhotos').onclick=async()=>{try{const ms=allocator.collect();if(!ms.length){toast('请先选择照片');return}await commit({...state,places:state.places.map(p=>({...p,media:[...p.media,...ms.filter(m=>m.target===p.id).map(({target,...m})=>m)]}))});tripManager(id);toast('照片已分配并保存')}catch(e){error(e)}}}
function batchForm(){show(`<h2>一次收藏，多个地方</h2><p class="hint">每行输入“国家 + 城市 / 地名”，最多 12 个。中文名找不到时可试当地名称、英文名或国家 + 邮编，例如 USA Savannah、USA 31401。</p><label for="batchText">地点列表 <span class="required">*</span></label><textarea id="batchText" placeholder="USA Savannah\n日本 京都 清水寺"></textarea><label for="batchTrip">归入旅行 / 分类（选填）</label><select id="batchTrip">${tripOptions(selected)}</select>${categoryEditor('batchTrip')}<button id="batchSearch" style="margin-top:15px">查找地点</button><div id="batchResults"></div>${allocatorMarkup()}<div class="actions"><button onclick="closeModal()">取消</button><button class="primary" id="batchSave" disabled>保存地点与照片</button></div>`);bindCategoryEditor('batchTrip');let found=[],searching=false;const targets=()=>found.filter(f=>f.chosen).map(f=>({id:f.id,name:f.name}));const allocator=photoAllocator(targets);const root=modal.querySelector('#batchResults');$('batchSearch').onclick=async()=>{const lines=$('batchText').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!lines.length||lines.length>12){toast('请输入 1–12 个地点，每行一个');return}const searchButton=$('batchSearch'),save=$('batchSave');searching=true;searchButton.disabled=true;save.disabled=true;try{const next=[];for(const name of lines){searchButton.textContent=`正在查找 ${next.length+1}/${lines.length}`;const rs=await lookup(name);if(!root.isConnected)return;const old=found.find(f=>f.name===name);next.push({id:old?.id||uid(),name,rs,chosen:null})}found=next;root.innerHTML=found.map((f,i)=>`<label for="batchResult${i}">${esc(f.name)}</label><select id="batchResult${i}" data-batch="${i}"><option value="">${f.rs.length?'选择准确位置，或留空跳过':'没有找到，尝试当地名称或邮编'}</option>${f.rs.map((r,j)=>`<option value="${j}">${esc(r.display_name)}</option>`).join('')}</select>`).join('');root.querySelectorAll('[data-batch]').forEach(s=>s.onchange=()=>{found[+s.dataset.batch].chosen=s.value===''?null:found[+s.dataset.batch].rs[+s.value];allocator.refresh()});allocator.refresh();save.disabled=false}catch(e){error(e)}finally{searching=false;searchButton.disabled=false;searchButton.textContent='重新查找'}};$('batchSave').onclick=async()=>{if(searching)return;try{const photos=allocator.collect(),trip=$('batchTrip').value;const records=found.filter(f=>f.chosen).map(f=>({id:f.id,name:f.name,lat:+f.chosen.lat,lng:+f.chosen.lon,trip,date:'',note:'',country:f.chosen.address?.country||'',city:f.chosen.address?.city||f.chosen.address?.town||f.chosen.address?.village||f.chosen.address?.municipality||'',visitPlace:'',media:photos.filter(m=>m.target===f.id).map(({target,...m})=>m)}));if(!records.length){toast('请至少选择一个准确地点');return}await commit({...state,places:[...state.places,...records]});closeModal();fit();toast(`已保存 ${records.length} 个地点和 ${photos.length} 份藏品`)}catch(e){error(e)}}}
let photoPins=false;
$('mapPhotos').onclick=()=>{photoPins=!photoPins;$('mapPhotos').setAttribute('aria-pressed',String(photoPins));$('mapPhotos').textContent=photoPins?'⌖ 普通图钉':'▧ 照片图钉';renderMap()};
function renderMap(){if(!layer||!map)return;layer.clearLayers();$('mapPhotos').hidden=view!=='map';const ps=visible().filter(hasCoordinates),zoom=map.getZoom(),groups=[];for(const p of ps){const xy=map.project([p.lat,p.lng],zoom);let group=groups.find(g=>g.center.distanceTo(xy)<(photoPins?66:48));if(!group){groups.push({points:[p],center:xy});continue}group.points.push(p);const n=group.points.length;group.center=L.point((group.center.x*(n-1)+xy.x)/n,(group.center.y*(n-1)+xy.y)/n)}for(const t of state.trips){const route=ps.filter(p=>p.trip===t.id);if(route.length>1)L.polyline(route.map(p=>[p.lat,p.lng]),{color:cleanMarker(t.marker).color,weight:zoom<5?1:2,dashArray:'5 8',opacity:zoom<5?.25:.55,interactive:false}).addTo(layer)}for(const g of groups){if(g.points.length>1){const pos=map.unproject(g.center,zoom);const marker=L.marker(pos,{icon:L.divIcon({className:'cluster-marker',html:`<span class="cluster-badge ${g.points.length>9?'large':''}">${g.points.length}</span>`,iconSize:[40,40],iconAnchor:[20,20]}),title:`${g.points.length} 个地点，点击展开`}).addTo(layer);marker.bindTooltip(`${g.points.length} 个地点 · 点击展开`);marker.on('click',()=>{const bounds=L.latLngBounds(g.points.map(p=>[p.lat,p.lng]));const same=g.points.every(p=>Math.abs(p.lat-g.points[0].lat)<.00001&&Math.abs(p.lng-g.points[0].lng)<.00001);if(zoom>=17||same){showCluster(g.points);return}map.fitBounds(bounds,{padding:[70,70],maxZoom:Math.min(18,zoom+3)});});continue}const p=g.points[0],photos=p.media.filter(m=>m.kind==='photo');let icon=markerIcon(state.trips.find(t=>t.id===p.trip),p);if(photoPins&&photos.length)icon=L.divIcon({className:'photo-pin',html:`<img class="pin-cover" src="${photos[0].data}" alt="${esc(p.name)}"><span class="photo-pin-count">${photos.length}</span><span class="photo-pin-dot"></span>${typeof visitPinBadge==='function'?visitPinBadge(p):''}`,iconSize:[52,42],iconAnchor:[26,42]});const marker=L.marker([p.lat,p.lng],{icon,title:p.name}).addTo(layer);marker.bindTooltip(esc(p.name)+(p.media.length?` · ${p.media.length} 份藏品`:''));marker.on('click',()=>detail(p.id))}}
function showCluster(points){show(`<h2>这里收藏了 ${points.length} 个地点</h2><p class="hint">位置相同或非常接近，选择一个地点翻阅。</p><div class="cluster-list">${points.map(p=>`<button class="result" data-cluster-place="${p.id}">${esc(p.name)} · ${p.media.length} 份藏品 →</button>`).join('')}</div>`);modal.querySelectorAll('[data-cluster-place]').forEach(b=>b.onclick=()=>detail(b.dataset.clusterPlace))}
function renderGallery(){const kind=view==='stamps'?'stamp':'photo';const locations=visible().map(p=>({p,ms:p.media.filter(m=>m.kind===kind)})).filter(x=>x.ms.length);$('gallery').innerHTML=locations.length?locations.map(({p,ms})=>`<article class="card gallery-location ${kind==='stamp'?'stamp':''}"><button class="photo-open" data-gallery="${p.id}" aria-label="打开 ${esc(p.name)} 的${ms.length}张藏品"><img src="${ms[0].data}" alt="${esc(p.name)}的收藏封面"><h3>${esc(p.name)}<span class="photo-count">${ms.length} 张</span></h3></button>${typeof visitBadge==='function'?visitBadge(p):''}<span class="hint">${esc(p.date||'未注明日期')} · ${esc(state.trips.find(t=>t.id===p.trip)?.name||'未分类足迹')}</span></article>`).join(''):`<div class="empty">${kind==='stamp'?'◉':'▧'}<h3>这里，留给下一份珍藏。</h3><p>打开旅程，批量上传照片并分配到地点。这里会按地点展示相册。</p><button onclick="placeForm()">收藏地点</button></div>`;document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>openViewer(b.dataset.gallery,null,kind))}
function openViewer(placeId,mediaId,kind){const p=state.places.find(p=>p.id===placeId);if(!p)return;const ms=p.media.filter(m=>!kind||m.kind===kind);if(!ms.length)return;let index=Math.max(0,ms.findIndex(m=>m.id===mediaId));const box=document.createElement('dialog');box.className='lightbox';document.body.appendChild(box);box.addEventListener('close',()=>box.remove());function draw(){const m=ms[index];box.innerHTML=`<button type="button" class="modal-x" aria-label="关闭照片">×</button><h2>${esc(p.name)}</h2><div class="lightbox-nav"><button data-prev ${index===0?'disabled':''} aria-label="上一张照片">← 上一张</button><span>${index+1} / ${ms.length} · ${m.kind==='stamp'?'邮戳与印章':'旅行照片'}</span><button data-next ${index===ms.length-1?'disabled':''} aria-label="下一张照片">下一张 →</button></div><figure><img src="${m.data}" alt="${esc(m.name)}"><figcaption>${esc(m.name)}${m.capturedAt?' · 拍摄于 '+esc(m.capturedAt):(p.date?' · '+esc(p.date):'')}</figcaption></figure><div class="lightbox-tools"><button data-adjust>旋转 / 翻转</button><a href="${m.data}" download="${esc(m.name)}">下载图片</a><button data-place>查看地点回忆</button></div>`;box.querySelector('[data-adjust]').onclick=()=>editPhoto(p.id,m.id,()=>{box.close();openViewer(p.id,m.id,kind)});box.querySelector('.modal-x').onclick=()=>box.close();box.querySelector('[data-prev]').onclick=()=>{if(index>0){index--;draw()}};box.querySelector('[data-next]').onclick=()=>{if(index<ms.length-1){index++;draw()}};box.querySelector('[data-place]').onclick=()=>{box.close();detail(p.id)}}box.onkeydown=e=>{if(e.key==='ArrowLeft'&&index>0){e.preventDefault();index--;draw()}if(e.key==='ArrowRight'&&index<ms.length-1){e.preventDefault();index++;draw()}};draw();box.showModal()}
async function movePlace(tripId,placeId,direction){const ps=state.places.filter(p=>p.trip===tripId),i=ps.findIndex(p=>p.id===placeId),j=i+direction;if(i<0||j<0||j>=ps.length)return;[ps[i],ps[j]]=[ps[j],ps[i]];try{await commit({...state,places:[...state.places.filter(p=>p.trip!==tripId),...ps]});tripManager(tripId);toast('顺序已保存，地图路线已更新')}catch(e){error(e)}}
function confirmTripDelete(id){const t=state.trips.find(t=>t.id===id);if(!t)return;const ps=state.places.filter(p=>p.trip===id),count=ps.reduce((n,p)=>n+p.media.length,0);show(`<h2>删除这段旅程？</h2><p>“${esc(t.name)}”及其 ${ps.length} 个地点、${count} 份藏品将一起移入回收站。</p><p class="hint">可以在回收站完整恢复，包括路线顺序和图钉设置。</p><div class="actions"><button id="keepTrip">取消</button><button class="danger" id="moveTripToTrash">移入回收站</button></div>`);$('keepTrip').onclick=()=>tripManager(id);$('moveTripToTrash').onclick=async()=>{try{await commit(TrashModel.removeTrip(state,id));closeModal();toast('旅程已移入回收站，可随时恢复')}catch(e){error(e)}}}
$('trashButton').onclick=()=>showTrash();
function trashDescription(e){if(e.kind==='trip')return `旅行分类 · ${e.places.length} 个地点 · ${e.places.reduce((n,x)=>n+x.place.media.length,0)} 份藏品`;if(e.kind==='place')return `地点 · ${e.place.media.length} 份藏品 · ${e.trip?.name||'未分类足迹'}`;return `${e.media.kind==='stamp'?'邮戳 / 印章':'照片'} · ${e.place.name}`}
function showTrash(){const entries=state.trash||[];show(`<div class="eyebrow">RECYCLE BIN / 回收站</div><h2>暂别的回忆</h2><p class="hint">删除的旅程、地点和藏品保存在这里，不会自动清空。恢复藏品时，若原地点或分类已不存在，会同时重建所需的地点和分类。</p><div class="toolbar"><button id="restoreAll" ${entries.length?'':'disabled'}>全部恢复</button><button id="purgeAll" class="danger" ${entries.length?'':'disabled'}>清空回收站</button><span class="hint">${entries.length} 项</span></div><div id="trashConfirm" role="status"></div><div>${[...entries].reverse().map(e=>`<article class="trash-item">${e.kind==='media'?`<img src="${e.media.data}" alt="${esc(e.name)}">`:''}<div class="trash-info"><h3>${esc(e.name)}</h3><div class="trash-meta">${esc(trashDescription(e))}<br>删除于 ${esc(new Date(e.deletedAt).toLocaleString('zh-CN'))}</div></div><div class="actions"><button data-restore="${e.id}">恢复</button><button data-purge="${e.id}" class="danger">永久删除</button></div></article>`).join('')||'<div class="empty">回收站是空的。<p>删除的回忆会先来到这里。</p></div>'}</div>`);modal.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>restoreTrash([b.dataset.restore]));modal.querySelectorAll('[data-purge]').forEach(b=>b.onclick=()=>confirmPurge([b.dataset.purge]));$('restoreAll').onclick=()=>restoreTrash(entries.map(e=>e.id));$('purgeAll').onclick=()=>confirmPurge(entries.map(e=>e.id),true)}
async function restoreTrash(ids){try{await commit(TrashModel.restore(state,ids));showTrash();toast('已恢复，可在地图和相册中查看')}catch(e){error(e)}}
function confirmPurge(ids,all=false){const entries=state.trash.filter(e=>ids.includes(e.id));if(!entries.length)return;const label=all?`回收站中的全部 ${entries.length} 项`:`“${entries[0].name}”`;const panel=$('trashConfirm');panel.innerHTML=`<div class="trash-confirm"><strong>永久删除${esc(label)}？</strong><p>包含其中的地点、照片和邮戳。此操作无法撤销，已导出的备份文件不受影响。</p><div class="actions"><button id="cancelPurge">取消</button><button id="confirmPurge" class="danger">${all?'确认清空回收站':'确认永久删除'}</button></div></div>`;panel.scrollIntoView({block:'nearest'});$('cancelPurge').onclick=()=>panel.innerHTML='';$('confirmPurge').onclick=async()=>{try{await commit(TrashModel.purge(state,ids));showTrash();toast(all?'回收站已清空':'已永久删除')}catch(e){error(e)}}}
function readBackup(d){if(d.format!=='paper-atlas-v1'||!Array.isArray(d.trips)||!Array.isArray(d.places)||(d.trash!==undefined&&!Array.isArray(d.trash)))throw Error('不是有效的行迹备份');const ids=new Map();function id(old){if(typeof old!=='string'||!old)throw Error('备份标识不完整');if(!ids.has(old))ids.set(old,uid());return ids.get(old)}function text(v,max){if(typeof v!=='string')throw Error('备份文字数据不完整');return v.slice(0,max)}function media(m){if(!m||typeof m.data!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(m.data))throw Error('备份图片格式不受支持');return{originalData:typeof m.originalData==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(m.originalData)?m.originalData:undefined,id:id(m.id),name:text(m.name,200),kind:m.kind==='stamp'?'stamp':'photo',data:m.data,capturedAt:typeof m.capturedAt==='string'?m.capturedAt.slice(0,60):''}}function trip(t){return t?{id:id(t.id),name:text(t.name,80),marker:cleanMarker(t.marker)}:null}function place(p){if(!p||!((p.lat===null&&p.lng===null)||hasCoordinates(p))||!Array.isArray(p.media))throw Error('备份地点数据不完整');return{countryTag:typeof p.countryTag==='string'?p.countryTag:'',cityTag:typeof p.cityTag==='string'?p.cityTag:'',id:id(p.id),name:text(p.name,160),city:typeof p.city==='string'?p.city.slice(0,100):'',country:typeof p.country==='string'?p.country.slice(0,100):'',visitPlace:typeof p.visitPlace==='string'?p.visitPlace.slice(0,160):'',lat:p.lat,lng:p.lng,trip:p.trip?id(p.trip):'',date:typeof p.date==='string'?p.date:'',note:typeof p.note==='string'?p.note:'',media:p.media.map(media)}}function position(v){return Number.isInteger(v)&&v>=0?v:0}const result={geoTags:Array.isArray(d.geoTags)?d.geoTags.filter(t=>t&&typeof t.id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(t.id)&&typeof t.country==='string'&&/^[A-Z]{2}$/.test(t.country)&&typeof t.name==='string'&&t.name.length<=100):[],visitCounts:Object.fromEntries(Object.entries(d.visitCounts||{}).filter(([k,v])=>k.length<300&&/^(place|country|city):/.test(k)&&Number.isInteger(v)&&v>0&&v<=9999)),trips:d.trips.map(trip),places:d.places.map(place),trash:(d.trash||[]).map(e=>{if(!['trip','place','media'].includes(e.kind))throw Error('回收站数据不完整');const base={id:uid(),kind:e.kind,name:text(e.name,200),deletedAt:Number.isNaN(Date.parse(e.deletedAt))?new Date().toISOString():e.deletedAt,trip:trip(e.trip),tripIndex:position(e.tripIndex)};if(e.kind==='trip'){if(!base.trip||!Array.isArray(e.places))throw Error('回收站旅程数据不完整');return{...base,places:e.places.map(x=>({place:place(x.place),index:position(x.index)}))}}if(e.kind==='place')return{...base,place:place(e.place),index:position(e.index)};return{...base,place:place(e.place),index:position(e.index),media:media(e.media),mediaIndex:position(e.mediaIndex)}})};if(result.trips.some(t=>!t))throw Error('备份分类数据不完整');return result}

function hasCoordinates(p){return Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Math.abs(p.lat)<=85&&Math.abs(p.lng)<=180}
function moveRecords(ids,from){show(`<h2>整理到旅行分类</h2><p class="hint">已选择 ${ids.length} 个地点，照片和回忆将一起移动。</p><label for="moveTarget">目标旅行</label><select id="moveTarget">${tripOptions(from)}</select>${categoryEditor('moveTarget')}<div class="actions"><button id="cancelMove">取消</button><button class="primary" id="confirmMove">移动地点</button></div>`);bindCategoryEditor('moveTarget');$('cancelMove').onclick=()=>tripManager(from);$('confirmMove').onclick=async()=>{try{const target=$('moveTarget').value;await commit({...state,places:state.places.map(p=>ids.includes(p.id)?{...p,trip:target}:p)});selected=target;render();tripManager(target);toast('已更新旅行分类')}catch(e){error(e)}}}

async function editPhoto(placeId,mediaId,onSaved){const p=state.places.find(p=>p.id===placeId),m=p?.media.find(m=>m.id===mediaId);if(!m)return;const editor=document.createElement('dialog');editor.className='lightbox';editor.innerHTML='<h2>调整照片</h2><p class="hint">左右旋转 90° 或水平翻转，预览满意后保存。恢复原图指恢复导入时保存的照片。</p><canvas style="display:block;max-width:100%;max-height:55vh;margin:auto;object-fit:contain"></canvas><div class="actions"><button data-left>↶ 左转</button><button data-right>↷ 右转</button><button data-flip>↔ 水平翻转</button><button data-reset>恢复原图</button><button data-cancel>取消</button><button data-save class="primary">保存调整</button></div>';document.body.appendChild(editor);editor.addEventListener('close',()=>editor.remove());editor.showModal();const canvas=editor.querySelector('canvas'),ctx=canvas.getContext('2d');let rotation=0,flip=false,base=m.data,bitmap,busy=false;function draw(){if(!bitmap)return;const quarter=rotation%180!==0;canvas.width=quarter?bitmap.height:bitmap.width;canvas.height=quarter?bitmap.width:bitmap.height;ctx.translate(canvas.width/2,canvas.height/2);ctx.scale(flip?-1:1,1);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(bitmap,-bitmap.width/2,-bitmap.height/2)}async function load(){busy=true;editor.querySelector('[data-save]').disabled=true;try{bitmap?.close();bitmap=await createImageBitmap(await(await fetch(base)).blob());draw()}catch(e){error(e)}finally{busy=false;editor.querySelector('[data-save]').disabled=!bitmap}}editor.addEventListener('close',()=>bitmap?.close());editor.querySelector('[data-left]').onclick=()=>{if(!busy){rotation=(rotation+270)%360;draw()}};editor.querySelector('[data-right]').onclick=()=>{if(!busy){rotation=(rotation+90)%360;draw()}};editor.querySelector('[data-flip]').onclick=()=>{if(!busy){flip=!flip;draw()}};editor.querySelector('[data-reset]').onclick=()=>{if(!busy){base=m.originalData||m.data;rotation=0;flip=false;load()}};editor.querySelector('[data-cancel]').onclick=()=>editor.close();editor.querySelector('[data-save]').onclick=async()=>{if(busy||!bitmap)return;busy=true;editor.querySelector('[data-save]').disabled=true;try{const data=rotation===0&&!flip?base:canvas.toDataURL('image/jpeg',.94);const next={...state,places:state.places.map(p=>p.id===placeId?{...p,media:p.media.map(x=>x.id===mediaId?{...x,originalData:x.originalData||x.data,data}:x)}:p)};await commit(next);editor.close();onSaved();toast('照片方向已保存')}catch(e){error(e);busy=false;editor.querySelector('[data-save]').disabled=false}};await load()}
function privacyInfo(){show(`<div class="eyebrow">YOUR PHOTOS, YOUR MEMORIES</div><h2>照片用途与隐私说明</h2><p class="hint">更新于 2026 年 11 月 9 日 · 本说明描述行迹当前版本的实际处理方式。</p><h3>照片用来做什么？</h3><p>用于展示旅行回忆、地图照片图钉、照片整理及你主动导出的手札。本站代码没有接入广告、售卖照片或将照片发送给 AI 分析／训练的功能；托管平台自身的数据政策由该平台规定。</p><h3>何时上传？</h3><p>选择照片后，读取拍摄时间和 GPS、格式转换、压缩与旋转均在浏览器中处理。默认保存在本机浏览器；只有点击“保存到云端”才上传当前记录及照片（包括回收站与用于恢复的照片原图）到此站的云存储。拍摄位置和时间也属于你的记录。</p><h3>谁能访问？</h3><p>在线主站当前为私密访问。云端接口要求登录，并按当前账户隔离记录和图片。本机数据可被能访问同一设备和浏览器的人查看。这里没有端到端加密，无法保证托管服务方无法接触数据。</p><h3>地图与搜索</h3><p>在线底图由 OpenStreetMap 提供，会接收地图请求与网络信息；地名搜索会将你输入的查询发送给 Nominatim。照片图像不会因浏览地图或搜索地点发送给它们。本地离线国界地图无需请求地图服务，搜索仍需联网。</p><h3>分享和导出</h3><p>分享手札会把所选旅程的照片、地点、日期和文字嵌入 HTML。完整备份／便携 HTML 还包含其他旅程、回收站及恢复用原图；导出文件没有密码保护，拿到文件的人可查看，发出后无法远程撤回。</p><h3>删除意味着什么？</h3><p>移入回收站后可恢复。永久删除会从当前记录中移除；已同步的云端记录需要再次保存到云端才更新。目前云存储没有自动清理失去引用的旧图片，因此永久删除记录不代表云端图片文件已彻底擦除。平台备份、其他设备副本与已导出文件也不会自动删除。</p><p class="hint">本地版不提供云端同步。浏览器缓存可能被清理，请自行保存备份；如不希望上传照片，可继续只使用本地版。</p><div class="actions"><button onclick="closeModal()">知道了</button></div>`)}

$('privacyInfo').onclick=privacyInfo;

