function geoPickerMarkup(p={}){return `<fieldset style="border:1px dashed var(--line);padding:12px"><legend>国家与城市标签（选填）</legend><p class="hint">先选国家，再选城市。城市可用“奥兰多 / Orlando”命名；以后复用同一标签即可，不按照片标题猜测。${p.country||p.city?'旧记录：'+esc([p.country,p.city].filter(Boolean).join(' · '))+'；请选择标签确认。':''}</p><label for="geoCountrySearch">搜索国家 / 地区</label><input id="geoCountrySearch" placeholder="中文、英文或国家代码"><select id="geoCountry" aria-label="国家标签"></select><label for="geoCitySearch">搜索常用城市标签</label><input id="geoCitySearch" placeholder="输入城市名称或别名"><select id="geoCity" aria-label="城市标签"></select><div class="row"><input id="geoNewCity" maxlength="100" placeholder="新城市标签，例如：奥兰多 / Orlando"><button type="button" id="geoCreate">保存为常用标签</button></div><p class="hint">同名城市建议带上州／省。找不到时才新建，已有标签请直接选用。国家选过后会排在列表前面。</p></fieldset>`}
function bindGeoPicker(p={}){let country=p.countryTag||'',city=p.cityTag||'';const cs=$('geoCountry'),ci=$('geoCity');function countries(){const q=$('geoCountrySearch').value.toLowerCase(),used=new Set(state.places.map(p=>p.countryTag));cs.innerHTML='<option value="">暂不设置国家</option>'+GeoCountries.filter(c=>c.code===country||[c.name,c.en,c.code].join(' ').toLowerCase().includes(q)).sort((a,b)=>Number(used.has(b.code))-Number(used.has(a.code))||a.name.localeCompare(b.name,'zh')).map(c=>`<option value="${c.code}" ${country===c.code?'selected':''}>${used.has(c.code)?'★ ':''}${esc(c.name)} · ${esc(c.en)}</option>`).join('')}function cities(){const q=$('geoCitySearch').value.toLowerCase();ci.innerHTML='<option value="">暂不设置城市</option>'+(state.geoTags||[]).filter(t=>t.country===country&&(t.id===city||t.name.toLowerCase().includes(q))).map(t=>`<option value="${t.id}" ${city===t.id?'selected':''}>${esc(t.name)}</option>`).join('');ci.disabled=!country;$('geoCreate').disabled=!country}countries();cities();$('geoCountrySearch').oninput=countries;$('geoCitySearch').oninput=cities;cs.onchange=()=>{country=cs.value;city='';$('geoCitySearch').value='';cities()};ci.onchange=()=>city=ci.value;$('geoCreate').onclick=async()=>{const name=$('geoNewCity').value.trim();if(!country||!name){toast('请先选国家并填写城市标签');return}const existing=(state.geoTags||[]).find(t=>t.country===country&&t.name.toLowerCase()===name.toLowerCase());const tag=existing||{id:uid(),country,name};try{if(!existing)await commit({...state,geoTags:[...(state.geoTags||[]),tag]});city=tag.id;$('geoCitySearch').value='';$('geoNewCity').value='';cities();toast('已选用常用城市标签')}catch(e){error(e)}};return ()=>{const c=GeoCountries.find(c=>c.code===cs.value),t=(state.geoTags||[]).find(t=>t.id===ci.value&&t.country===cs.value);return{countryTag:c?.code||'',cityTag:t?.id||'',country:c?.name||p.country||'',city:t?.name||(!c?p.city||'':'')}}}
function batchGeoTags(ids,trip){show(`<h2>为选中记录设置国家与城市</h2><p class="hint">只更新这 ${ids.length} 条记录的国家、城市标签；同一旅程内只计一次。</p>${geoPickerMarkup()}<div class="actions"><button id="geoCancel">取消</button><button id="geoApply" class="primary">应用标签</button></div>`);const read=bindGeoPicker();$('geoCancel').onclick=()=>tripManager(trip);$('geoApply').onclick=async()=>{const tags=read();if(!tags.countryTag){toast('请先选择国家');return}try{await commit({...state,places:state.places.map(p=>ids.includes(p.id)?{...p,...tags}:p)});tripManager(trip);toast('国家与城市标签已更新')}catch(e){error(e)}}}
